import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),i={name:"spec/index.md"};function n(s,e,d,c,p,l){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h1><p>These pages summarize the current Piwork implementation for developers. They adapt the source project&#39;s existing specifications; they do not define a competing API or package format.</p><p>The historical Linux image set documented here uses fixed release ID <code>0.0.7-62f2868cb8e2-d69916b52829-dirty</code> for Core, optional CLI, Agent, Files and Snapshots. Core includes the web workbench, Admin and first-time setup. Its build source is <code>62f2868cb8e24da3d08db7a7d6c00aabd6226cd4</code>, modified was true at build time, and input SHA256 is <code>d69916b5282972c9a336745e4efc30b749fad531a42ed5aac3c8b4dcad4c38ff</code>. Later documentation commits do not rewrite this provenance. See the <a href="/piwork/piwork/install/0.0.7-62f2868cb8e2-d69916b52829-dirty/release-manifest.json">release manifest</a> for fixed references and availability. The independent <a href="/piwork/piwork/install/0.0.7-62f2868cb8e2-d69916b52829-dirty/web-base-release.json">Web base receipt</a> identifies the NiceGUI environment. Historical installer directories retain their original provenance.</p><table tabindex="0"><thead><tr><th>Area</th><th>Read here</th><th>Authoritative source</th></tr></thead><tbody><tr><td>Portable Work</td><td><a href="/piwork/spec/work.html">Work Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">Package format</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work</a></td></tr><tr><td>Managed capabilities</td><td><a href="/piwork/spec/service.html">Service Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services</a> and <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP tools</a></td></tr><tr><td>Intelligent execution</td><td><a href="/piwork/spec/harness.html">Harness Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">piwork-brain</a></td></tr></tbody></table><h2 id="status-labels" tabindex="-1">Status labels <a class="header-anchor" href="#status-labels" aria-label="Permalink to &quot;Status labels&quot;">​</a></h2><ul><li><strong>Current behavior / format:</strong> implemented behavior and source contracts.</li><li><strong>Experimental:</strong> existing behavior whose contracts and user experience are still evolving.</li><li><strong>Future direction:</strong> a product goal that is not an implemented guarantee.</li></ul><p>For mismatches, prefer current implementation over older design notes. <a href="https://github.com/pphboy/piwork/issues" target="_blank" rel="noreferrer">Open an issue</a> with the command, image version, and observed result.</p><h2 id="current-delivery-boundary" tabindex="-1">Current delivery boundary <a class="header-anchor" href="#current-delivery-boundary" aria-label="Permalink to &quot;Current delivery boundary&quot;">​</a></h2><p>Core manages one local Linux Docker Engine through its Unix API. The unified application targets <code>linux/amd64</code> and Engine 28+; Linux/Windows browsers connect remotely; Compose 2.24+ is only needed for the Core Demo or advanced Compose setups. The native Core and CLI target Linux x86-64. The separate desktop launcher runs the Linux environment locally on Windows/Linux; see the source <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/cli-runtime-portability/spec.md" target="_blank" rel="noreferrer">CLI platform contract</a>.</p><p>A Work requires ready runtime images and model configuration. Core shutdown stops managed runtime containers while retaining durable state. Closing Desktop or the CLI does not stop the Work.</p><p><a href="/piwork/guide/quick-start.html">Quick Start</a> follows the desktop one-click path. Linux server maintenance remains documented under <a href="/piwork/guide/installation.html">Installation</a> and <a href="/piwork/guide/source-installation.html">Build from Source</a>.</p>',11)])])}const u=t(i,[["render",n]]);export{b as __pageData,u as default};
